const e = $input.first().json;

if (!e.to) {
  throw new Error('sub-enviar-whatsapp: campo "to" e obrigatorio.');
}

let corpo;

if (e.tipo === 'template') {
  if (!e.template_nome) {
    throw new Error('sub-enviar-whatsapp: tipo=template exige "template_nome".');
  }
  const params = e.template_params || [];
  corpo = {
    messaging_product: 'whatsapp',
    to: e.to,
    type: 'template',
    template: {
      name: e.template_nome,
      language: { code: e.template_idioma || 'pt_BR' },
      components: params.length
        ? [{ type: 'body', parameters: params.map(p => ({ type: 'text', text: String(p) })) }]
        : []
    }
  };
} else {
  if (!e.texto) {
    throw new Error('sub-enviar-whatsapp: tipo=text exige "texto".');
  }
  corpo = {
    messaging_product: 'whatsapp',
    to: e.to,
    type: 'text',
    text: { body: e.texto }
  };
}

return [{ json: { corpo } }];

const r = $input.first().json || {};
const ok = Array.isArray(r.messages) && r.messages.length > 0;

if (ok) {
  return [{ json: { ok: true, id_mensagem: r.messages[0].id, erro: null } }];
}

const err = r.error || {};
let erro = err.message || 'falha desconhecida no envio';

// 131047: a janela de 24h fechou. Texto livre nao passa mais; so template aprovado.
if (err.code === 131047) {
  erro = 'janela de 24h fechada (131047) -- so template aprovado reabre a conversa';
}

return [{ json: { ok: false, id_mensagem: null, erro, codigo: err.code || null } }];
